// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

/**
 * A planning query keeps the parser's raw names for execution, but its physical learning identities write the plan
 * identity's canonical ordinal for every name the identity canonicalizes, with a token no name can produce.
 */
class PackedCanonicalLearningNamesTest {

	private static final int FORMAT_BYTES = 1_000_000;
	private static final String HAVING = "SELECT ?s (COUNT(?o) AS ?n) WHERE { ?s <urn:p> ?o } GROUP BY ?s "
			+ "HAVING (COUNT(?o) > 1)";
	private static final String PATH = "SELECT ?s ?x WHERE { ?s <urn:p>/<urn:q> ?x }";
	private static final String VALUES_PATH = "SELECT ?s ?x WHERE { VALUES ?s { <urn:s1> <urn:s2> } "
			+ "?s <urn:p>/<urn:q> ?x }";
	private static final String PLAIN = "SELECT ?s ?x WHERE { ?s <urn:p> ?o . ?o <urn:q> ?x }";

	@Test
	void planningSourceIsEqualAcrossParsesOfOneQuery() {
		for (String text : List.of(HAVING, PATH, VALUES_PATH)) {
			TupleExpr first = parse(text);
			TupleExpr second = parse(text);
			assertNotEquals(internalNames(first), internalNames(second),
					"COVERAGE_PREREQUISITE: every parse generates new internal names for " + text);
			String firstSource = source(planning(first));
			String secondSource = source(planning(second));
			assertNotNull(firstSource);
			assertEquals(firstSource, secondSource, "the physical source of a planning query is parse-stable");
			for (Token token : tokens(firstSource)) {
				assertFalse(token.kind() == 'S' && token.text().startsWith("_anon_"),
						"no parser-generated name reaches the physical source: " + token);
			}
		}
	}

	@Test
	void familyConcretisationAndCachedRebindKeepTheCanonicalSource() {
		for (String text : List.of(HAVING, VALUES_PATH)) {
			TupleExpr older = parse(text);
			TupleExpr current = parse(text);
			String fresh = source(planning(current));
			PackedQueryFamilyIdentity family = PackedQueryFamilyIdentity.create(older, null);
			assertNotNull(family, "COVERAGE_PREREQUISITE: the query has a parameterized family");
			assertEquals(source(PackedQueryFamilyIdentity.create(current, null).concreteQuery()),
					source(family.concreteQuery()), "family concretisation of two parses");
			PackedQuery cached = planning(older).withoutOriginalBindingSets();
			PackedQuery rebound = PackedQueryCodec.rebindOriginalBindingSets(cached, current);
			assertEquals(fresh, source(rebound), "a cached older parse rebound to the current parse");
			assertEquals(fresh, source(rebound.withoutOriginalBindingSets()
					.withOriginalBindingSets(
							new Object[rebound.relationCount() + 1])),
					"every derived planning query keeps the ordinals");
		}
	}

	@Test
	void exactNamesAndConstantLabelsStayExactInThePhysicalSource() {
		TupleExpr plain = parse(PLAIN);
		List<Token> tokens = tokens(source(planning(plain)));
		Set<String> strings = new TreeSet<>();
		for (Token token : tokens) {
			assertTrue(token.kind() != 'A', "a query without internal names writes no canonical token");
			if (token.kind() == 'S') {
				strings.add(token.text());
			}
		}
		for (String name : namesOf(plain)) {
			assertTrue(strings.contains(name), "exact name " + name + " is written as itself");
		}
	}

	@Test
	void canonicalFrameTokenIsADedicatedTokenKind() {
		PackedQueryView canonical = new PackedQueryView(planning(rename(PLAIN, "o", Var.of("_anon_frame_1", true))));
		PackedQueryView userNamed = new PackedQueryView(planning(rename(PLAIN, "o", Var.of("anonymous-name"))));
		List<Token> canonicalFrame = tokens(frame(canonical, "_anon_frame_1"));
		List<Token> userFrame = tokens(frame(userNamed, "anonymous-name"));
		assertFalse(canonicalFrame.stream().anyMatch(token -> "_anon_frame_1".equals(token.text())));
		assertFalse(userFrame.stream().anyMatch(token -> token.kind() == 'A'));
		// Same frame position by position; only the name's own token differs, as one token of a different kind.
		assertEquals(canonicalFrame.size(), userFrame.size(), "one name is one token in either kind");
		int substituted = 0;
		for (int index = 0; index < canonicalFrame.size(); index++) {
			Token canonicalToken = canonicalFrame.get(index);
			Token userToken = userFrame.get(index);
			if (!canonicalToken.equals(userToken)) {
				assertEquals('A', canonicalToken.kind(), "the internal name is the canonical token at " + index);
				assertEquals(new Token('S', 0L, "anonymous-name"), userToken,
						"a user variable named like the identity's canonical tag stays an exact string token");
				substituted++;
			}
		}
		assertTrue(substituted > 0, "the internal output name is written as the canonical token: " + canonicalFrame);
		assertNotEquals(canonicalFrame, userFrame);
	}

	private record Token(char kind, long number, String text) {
	}

	/** Decodes the physical sink's complete ASCII stream; every token starts with its kind tag. */
	private static List<Token> tokens(String encoded) {
		assertNotNull(encoded);
		List<Token> tokens = new ArrayList<>();
		int index = 0;
		while (index < encoded.length()) {
			char kind = encoded.charAt(index++);
			switch (kind) {
			case 'L' -> {
				tokens.add(new Token(kind, Long.parseUnsignedLong(encoded.substring(index, index + 16), 16), null));
				index += 16;
			}
			case 'N' -> tokens.add(new Token(kind, 0L, null));
			case 'S' -> {
				int length = Integer.parseInt(encoded.substring(index, index + 8), 16);
				index += 8;
				StringBuilder text = new StringBuilder(length);
				for (int character = 0; character < length; character++) {
					text.append((char) Integer.parseInt(encoded.substring(index, index + 4), 16));
					index += 4;
				}
				tokens.add(new Token(kind, 0L, text.toString()));
			}
			case 'A' -> {
				tokens.add(new Token(kind, Long.parseLong(encoded.substring(index, index + 8), 16), null));
				index += 8;
			}
			default -> fail("undecodable physical identity token '" + kind + "' at " + (index - 1));
			}
		}
		assertEquals(encoded.length(), index, "the token stream decodes exactly");
		return tokens;
	}

	private static String frame(PackedQueryView view, String outputName) {
		for (int relation = 1; relation <= view.relationCount(); relation++) {
			if (view.isStatementPattern(relation) && view.outputBindingNames(relation).contains(outputName)) {
				try (var memory = owner()) {
					return view.tryPhysicalFrameIdentity(memory, relation,
							PackedCostTestSupport.prefixContext(new int[0], 0, 1.0d, 0), 0, FORMAT_BYTES);
				}
			}
		}
		fail("COVERAGE_PREREQUISITE: no statement pattern outputs " + outputName);
		return null;
	}

	private static String source(PackedQuery query) {
		try (var memory = owner()) {
			return new PackedQueryView(query).tryPhysicalSourceIdentity(memory, FORMAT_BYTES);
		}
	}

	private static PackedQuery planning(TupleExpr expression) {
		return PackedQueryCodec.encodeForPlanning(expression, null, PackedStatementPatternSemanticsCodec.NONE);
	}

	private static TupleExpr parse(String query) {
		return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
	}

	private static TupleExpr rename(String query, String from, Var replacement) {
		TupleExpr parsed = parse(query);
		List<Var> targets = new ArrayList<>();
		parsed.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Var node) {
				if (from.equals(node.getName())) {
					targets.add(node);
				}
			}
		});
		for (Var target : targets) {
			target.replaceWith(replacement.clone());
		}
		return parsed;
	}

	private static Set<String> internalNames(TupleExpr expression) {
		Set<String> names = new TreeSet<>();
		for (Map.Entry<String, Boolean> entry : variables(expression)) {
			if (entry.getValue()) {
				names.add(entry.getKey());
			}
		}
		return names;
	}

	private static Set<String> namesOf(TupleExpr expression) {
		Set<String> names = new TreeSet<>();
		for (Map.Entry<String, Boolean> entry : variables(expression)) {
			names.add(entry.getKey());
		}
		return names;
	}

	/** Every variable name with whether it is an unvalued internal (anonymous) variable. */
	private static List<Map.Entry<String, Boolean>> variables(TupleExpr expression) {
		List<Map.Entry<String, Boolean>> variables = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Var node) {
				variables.add(Map.entry(node.getName(), node.isAnonymous() && !node.hasValue()));
			}
		});
		return variables;
	}

	private static PackedCostTestSupport.ProviderMemoryOwner owner() {
		return PackedCostTestSupport.providerMemory(new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE));
	}
}
